/* @lc app=leetcode id=2471 lang=kotlin */
class Solution { fun minimumOperations(root: TreeNode?): Int = if (root == null) 0 else java.util.ArrayDeque<TreeNode>().apply { add(root) }.let { q -> generateSequence { if (q.isEmpty()) null else List(q.size) { q.poll() } }.sumOf { level -> level.map { it.`val` }.let { arr -> arr.sorted().withIndex().associate { it.value to it.index }.let { pos -> BooleanArray(arr.size).let { vis -> arr.indices.sumOf { i -> if (vis[i] || pos[arr[i]] == i) 0 else generateSequence(i) { curr -> if (vis[curr]) null else pos[arr[curr]].also { vis[curr] = true } }.count() - 1 } } } }.also { level.forEach { node -> node.left?.let { q.add(it) }.also { node.right?.let { q.add(it) } } } } } }